'use strict';
// Verified provider destinations; unknown catalog entries have no generated management URL.
const detailManagementLinks={Netflix:'https://www.netflix.com/account',Spotify:'https://www.spotify.com/account/manage-your-plan/'};
function detailEventInfo(r,today=calendarToday){if(r.status==='Expired')return {label:'Access ended',date:r.expiredAt||'',timing:'Expired'};if(r.status==='Cancelled')return {label:'Access until',date:r.accessUntil||r.renewal||'',timing:'Cancellation recorded'};if(r.trialEnded)return {label:'Trial ended',date:r.trialEnd,timing:'Auto-renew tracking off'};const date=r.trial?r.trialEnd:r.renewal;if(!date)return {label:r.trial?'Trial ends':'Next renewal',date:'',timing:'Add a renewal date'};const days=Math.round((Date.parse(date+'T00:00:00Z')-Date.parse(today+'T00:00:00Z'))/86400000);return {label:r.trial?'Trial ends':'Next renewal',date,timing:days===0?'Today':days===1?'Tomorrow':days>1?'In '+days+' days':'Date passed · check details'};}
function detailReceiptRows(r){return paymentReceiptHistory().filter(p=>p.recordId===r.id);}
function detailInboxContext(r){const email=r.source==='Gmail'?r.inboxEmail:detailReceiptRows(r)[0]?.inboxEmail;const inbox=profileInboxes.find(i=>i.email===email);if(!email)return {email:'',message:'No Gmail receipt linked yet.'};if(!inbox)return {email,message:'Inbox is no longer connected. Saved receipts stay available.'};return {email,message:inbox.status==='reconnect'?'Reconnect needed · saved receipts available':inbox.status==='paused'?'Updates paused · Last sync '+(inbox.lastSync||'not available'):'Last successful sync · '+(inbox.lastSync||'Not synced yet')};}
function detailReceiptLink(r){const receipts=detailReceiptRows(r),last=receipts[0];return `<button class="detail-payment-history" data-detail-payments="${escape(r.id)}"><span class="detail-history-icon" aria-hidden="true">${profileIcon('payments')}</span><span><strong>Payment history</strong><small>${last?'Last receipt · '+detailDate(last.paidDate)+' · '+escape(last.currency)+' '+Number(last.amount).toFixed(2):'No matching Gmail receipt yet'}</small></span><span aria-hidden="true">›</span></button>`;}
function subscriptionDetailReview(up){const r={...currentDetailRecord(),...(current==='Detail · cancelled'?{status:'Cancelled'}:{}),...(current==='Detail · no renewal'?{renewal:''}:{})},event=detailEventInfo(r),status=subscriptionStatus(r),others=allTrackedRecords().filter(p=>p.name===r.name&&p.id!==r.id),inbox=detailInboxContext(r),link=detailManagementLinks[r.name],inactive=['Cancelled','Expired'].includes(r.status)||r.trialEnded,auto=inactive?'Off':r.autoRenew===true?'On':r.autoRenew===false?'Off':'Not set';return `<div class="detail-review"><div class="head detail-head">${btn('‹','back','back')}<h2>Subscription</h2>${deleteIcon}</div><section class="detail-overview"><div class="detail-identity"><span class="avatar">${platformLogo(r.name)}</span><div><h3>${escape(r.name)}</h3><small>${escape(r.category||'Other')}${r.plan?' · '+escape(r.plan):''}</small></div><span class="detail-status status-${status.key}">${status.label}</span></div><div class="detail-cost"><strong><small>${escape(r.currency)}</small> ${Number(r.price).toFixed(2)}</strong><span>${r.trial?'After trial · ':''}${escape(r.cycle)}</span></div><div class="detail-next-event"><span>${event.label}</span><strong>${escape(event.timing)}${event.date?' · '+detailDate(event.date):''}</strong></div></section><section class="panel detail-billing"><h3>${r.trial?'Trial & billing':'Renewal & billing'}</h3>${fr('Billing cycle',escape(r.cycle))}${fr('Start date',detailDate(r.start))}${r.trial||r.trialEnded?fr('Trial ends',detailDate(r.trialEnd)):''}${fr('Auto-renew tracking',auto)}${fr('Reminder',inactive?'Off':!event.date?'Add a renewal date':`<button data-action="reminder" aria-haspopup="dialog">${reminderLabel(r)} ›</button>`)}${r.estimated&&event.date?`<p class="detail-estimate">${r.source==='Gmail'?'Date estimated from a receipt.':'Estimated date.'} ${r.status==='Cancelled'?'Review your next date when you track again.':'You can update it in Edit.'}</p>`:''}<p class="detail-tracking-note">Tracking doesn’t confirm a charge or change your service settings.</p></section>${detailReceiptLink(r)}<section class="panel detail-account"><div class="detail-account-top"><h3>${r.source==='Gmail'?'Connected email':'Added under'}</h3><span class="detail-source">${r.source==='Gmail'?'Gmail scan':r.source==='AI'?'Added with AI':'Added manually'}</span></div><p class="detail-email">${escape(detailEmail(r))}</p><p class="detail-account-caption">${r.source==='Gmail'?'The inbox where this subscription was found.':'Your Renewless account when this subscription was added.'}</p><div class="detail-sync-context"><span>${profileIcon('mail')}</span><div>${inbox.email&&r.source!=='Gmail'?`<strong>Receipt inbox · ${escape(inbox.email)}</strong>`:''}<small>${escape(inbox.message)}</small></div></div></section>${link?`<a class="detail-manage-link" href="${link}" target="_blank" rel="noopener noreferrer"><span>Manage on ${escape(r.name)}<small>Opens the service’s website</small></span><span aria-hidden="true">↗</span></a>`:''}${others.length?`<button class="detail-related-link" data-open-platform><span>More on ${escape(r.name)}<small>${others.length} other subscription${others.length===1?'':'s'}</small></span><span class="related-count">${others.length} <span aria-hidden="true">›</span></span></button>`:''}<section class="panel detail-note"><div class="detail-account-top"><h3>Notes</h3>${btn(r.note?'Edit note':'Add note','Edit','note-edit')}</div>${r.note?`<p>${escape(r.note)}</p>`:'<p class="muted">No notes added yet.</p>'}</section>${r.status==='Cancelled'?'<p class="note">Recorded in Renewless. Your subscription must be cancelled with the service.</p>':''}${up?'':detailActions()}</div>`;}
document.addEventListener('click',e=>{const link=e.target.closest('[data-detail-payments]');if(!link)return;paymentsView.recordId=link.dataset.detailPayments;paymentsView.recordName=currentDetailRecord().name;paymentsView.detailOrigin=current;paymentsView.query='';paymentsView.year='';paymentsView.month='all';go('Payments');});

let trackAgainTrigger=null;
function trackAgainDays(date,today){return Math.max(0,Math.round((Date.parse(date+'T00:00:00Z')-Date.parse(today+'T00:00:00Z'))/86400000))||0;}
function trackAgainErrors(values,today){const errors={},date=values.renewal,parsed=Date.parse(date+'T00:00:00Z');if(!values.amount||!Number.isFinite(Number(values.amount))||Number(values.amount)<=0)errors.amount='Enter an amount greater than zero.';if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(parsed)||new Date(parsed).toISOString().slice(0,10)!==date)errors.renewal='Choose your next renewal date.';else if(date<today)errors.renewal='Choose today or a future date.';if(values.reminder!=='off'&&(![1,3,5,7].includes(Number(values.reminder))||Number(values.reminder)>trackAgainDays(date,today)))errors.reminder='Choose a reminder that fits before renewal.';return errors;}
function resumedTrackingRecord(record,values){const next={...record,status:'Active',price:Number(values.amount).toFixed(2),renewal:values.renewal,estimated:false,previousCancellation:{cancelledAt:record.cancelledAt||'',accessUntil:record.accessUntil||''},trialDays:0,trialEnd:'',trialDuration:'No trial',trialEndSource:'',trial:false,trialEnded:false};if(record.trialEnd)next.previousTrial={start:record.start,end:record.trialEnd,days:record.trialDays,source:record.trialEndSource};delete next.cancelledAt;delete next.accessUntil;return next;}
function trackAgainReminderVisible(date,today){const parsed=Date.parse(date+'T00:00:00Z');return /^\d{4}-\d{2}-\d{2}$/.test(date)&&Number.isFinite(parsed)&&new Date(parsed).toISOString().slice(0,10)===date&&trackAgainDays(date,today)>0;}
function trackAgainReminderOptions(date){return ['off',...[1,3,5,7].filter(days=>days<=trackAgainDays(date,calendarToday)).map(String)].map(value=>({value,label:value==='off'?'Off':value+' day'+(value==='1'?'':'s')+' before'}));}
function closeTrackAgain(){const overlay=document.querySelector('.track-again-overlay');if(!overlay)return;const phone=overlay.closest('.phone');closeSelectMenu(false);overlay.remove();phone.querySelectorAll('[data-track-again-inert]').forEach(el=>{el.inert=false;el.removeAttribute('data-track-again-inert');});trackAgainTrigger?.focus();}
function openTrackAgain(trigger){trackAgainTrigger=trigger;const phone=trigger.closest('.phone'),r=currentDetailRecord(),date=r.renewal>=calendarToday?r.renewal:'',overlay=document.createElement('div');overlay.className='track-again-overlay';overlay.innerHTML=`<div class="track-again-shade" data-close-track-again></div><section class="track-again-sheet" role="dialog" aria-modal="true" aria-labelledby="track-again-title"><div class="handle"></div><header><div><h3 id="track-again-title">Track ${escape(r.name)} again</h3><p>Review your details before resuming.</p></div><button data-close-track-again aria-label="Close track again">×</button></header><form data-track-again-form novalidate><label>Amount <small>${escape(r.currency)} · ${escape(r.cycle)}</small><input name="amount" type="number" inputmode="decimal" min="0.01" step="0.01" value="${Number(r.price).toFixed(2)}" aria-describedby="track-amount-error"><span class="manual-error" id="track-amount-error" hidden></span></label><label>Next renewal<input name="renewal" type="date" min="${calendarToday}" value="${date}" aria-describedby="track-renewal-error"><span class="manual-error" id="track-renewal-error" hidden></span></label><div class="track-reminder-field" ${trackAgainReminderVisible(date,calendarToday)?'':'hidden'}>${selectField({label:'Reminder',name:'reminder',value:'off',options:trackAgainReminderOptions(date)})}<span class="manual-error" id="track-reminder-error" hidden></span></div><p class="track-again-note">This resumes tracking in Renewless. Reactivate your subscription with ${escape(r.name)} separately.</p><button type="submit" class="primary">Resume tracking</button></form></section>`;for(const el of phone.children){if(!el.inert){el.inert=true;el.dataset.trackAgainInert='true';}}phone.append(overlay);syncSelectControls();overlay.querySelector('[data-close-track-again]').focus();}
document.addEventListener('click',e=>{const open=e.target.closest('[data-track-again]'),close=e.target.closest('[data-close-track-again]');if(open)openTrackAgain(open);else if(close)closeTrackAgain();});
document.addEventListener('change',e=>{const form=e.target.closest('[data-track-again-form]');if(!form||e.target.name!=='renewal')return;const value=form.elements.reminder.value,options=trackAgainReminderOptions(e.target.value),wrapper=form.querySelector('.track-reminder-field');wrapper.hidden=!trackAgainReminderVisible(e.target.value,calendarToday);wrapper.innerHTML=selectField({label:'Reminder',name:'reminder',value:options.some(o=>o.value===value)?value:'off',options})+'<span class="manual-error" id="track-reminder-error" hidden></span>';syncSelectControls();});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-track-again-form]');if(!form)return;e.preventDefault();const values={amount:form.elements.amount.value,renewal:form.elements.renewal.value,reminder:form.elements.reminder.value},errors=trackAgainErrors(values,calendarToday);for(const key of ['amount','renewal','reminder']){const field=form.elements[key],error=form.querySelector('#track-'+key+'-error');error.textContent=errors[key]||'';error.hidden=!errors[key];field.setAttribute('aria-invalid',String(!!errors[key]));if(key==='reminder')field.parentElement.querySelector('[data-select-trigger]').setAttribute('aria-invalid',String(!!errors[key]));}if(Object.keys(errors).length){form.elements[Object.keys(errors)[0]].focus();return;}const r=resumedTrackingRecord(currentDetailRecord(),values);trialRecords.set(recordKey(r),r);state.manual=r;reminderPreferences.set(r.id,values.reminder==='off'?{mode:'off',days:0}:{mode:'once',days:Number(values.reminder)});closeTrackAgain();go('Detail');toast('Tracking resumed in Renewless.');});
document.addEventListener('keydown',e=>{const overlay=document.querySelector('.track-again-overlay');if(!overlay||e.defaultPrevented)return;if(e.key==='Escape'){e.preventDefault();closeTrackAgain();}else if(e.key==='Tab'){const controls=[...overlay.querySelectorAll('button,input:not([type=hidden])')].filter(el=>!el.disabled&&el.getClientRects().length),first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
